<?php declare(strict_types=1);
$annualPostingOld=$_POST;$annualPostingMeta=null;$annualPostingExisting=null;$annualPostingCurrent=null;$annualPostingRecoveryError=null;$annualPostingRetry=false;
try{
    $annualPostingMeta=\Kulturhus\Verein\BalancePostingForm::metadata($annualPostingOld);
    $annualPostingReader=new \Kulturhus\Verein\BalancePostingOriginalRead($db,(string)$_SESSION['actor']);
    $annualPostingExisting=$annualPostingReader->fromSubmitted($annualPostingOld);
    $annualPostingCurrent=$annualPostingExisting['current']??(new \Kulturhus\Verein\BalanceLedger($db,(string)$_SESSION['actor']))->report($annualPostingMeta['year']);
    $annualPostingRetry=$annualPostingExisting===null&&\Kulturhus\Verein\BalancePostingForm::complete($annualPostingOld)&&$annualPostingCurrent['state']==='open'&&$annualPostingCurrent['version']===$annualPostingMeta['version']&&\Kulturhus\Verein\BalanceLedger::enabled()&&\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor'])['finance_access']==='write'&&((new \Kulturhus\Verein\Settings($db,(string)$_SESSION['actor']))->section('tax')['data']['accounting_basis']??'euer')==='balance';
    if($annualPostingRetry&&$annualPostingMeta['action']==='balance-reverse'){
        $base=null;$alreadyReversed=false;foreach($annualPostingCurrent['entries']as$entry){if($entry['id']===$annualPostingOld['entry'])$base=$entry;if($entry['reversal_of']===$annualPostingOld['entry'])$alreadyReversed=true;}
        $actor=\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor']);$sourceOwned=\Kulturhus\Verein\DocumentCatalog::query($db,'SELECT 1 FROM balance_sources WHERE club_id=? AND tax_year=? AND JSON_CONTAINS(entry_ids,JSON_QUOTE(?))',[$actor['club_id'],$annualPostingMeta['year'],$annualPostingOld['entry']])->fetchColumn();
        $annualPostingRetry=$base!==null&&$base['reversal_of']===null&&!$alreadyReversed&&!$sourceOwned;
    }
}catch(DomainException $failure){$annualPostingRecoveryError=$failure->getMessage();}
$annualPostingAccounts=$annualPostingCurrent['accounts']??[];
